import { createRoute, z } from '@hono/zod-openapi'

type BooleanOperatorType = 'And' | 'Or'

const S3DataTypeSchema = z
  .enum(['ManifestFile', 'S3Prefix', 'AugmentedManifestFile'])
  .openapi('S3DataType')

const S3UriSchema = z
  .string()
  .regex(/^(https|s3):\/\/([^\/]+)\/?(.*)$/)
  .max(1024)
  .openapi('S3Uri')

const S3DataDistributionSchema = z
  .enum(['FullyReplicated', 'ShardedByS3Key'])
  .openapi('S3DataDistribution')

const AttributeNameSchema = z.string().regex(/.+/).min(1).max(256).openapi('AttributeName')

const AttributeNamesSchema = z.array(AttributeNameSchema).max(16).openapi('AttributeNames')

const InstanceGroupNameSchema = z.string().regex(/.+/).min(1).max(64).openapi('InstanceGroupName')

const InstanceGroupNamesSchema = z
  .array(InstanceGroupNameSchema)
  .max(5)
  .openapi('InstanceGroupNames')

const S3DataSourceSchema = z
  .object({
    S3DataType: S3DataTypeSchema.and(
      z
        .any()
        .openapi({
          description:
            "<p>If you choose <code>S3Prefix</code>, <code>S3Uri</code> identifies a key name prefix. SageMaker uses all objects that match the specified key name prefix for model training. </p> <p>If you choose <code>ManifestFile</code>, <code>S3Uri</code> identifies an object that is a manifest file containing a list of object keys that you want SageMaker to use for model training. </p> <p>If you choose <code>AugmentedManifestFile</code>, S3Uri identifies an object that is an augmented manifest file in JSON lines format. This file contains the data you want to use for model training. <code>AugmentedManifestFile</code> can only be used if the Channel's input mode is <code>Pipe</code>.</p>",
        }),
    ),
    S3Uri: S3UriSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>Depending on the value specified for the <code>S3DataType</code>, identifies either a key name prefix or a manifest. For example: </p> <ul> <li> <p> A key name prefix might look like this: <code>s3://bucketname/exampleprefix</code> </p> </li> <li> <p> A manifest might look like this: <code>s3://bucketname/example.manifest</code> </p> <p> A manifest is an S3 object which is a JSON file consisting of an array of elements. The first element is a prefix which is followed by one or more suffixes. SageMaker appends the suffix elements to the prefix to get a full set of <code>S3Uri</code>. Note that the prefix must be a valid non-empty <code>S3Uri</code> that precludes users from specifying a manifest whose individual <code>S3Uri</code> is sourced from different S3 buckets.</p> <p> The following code example shows a valid manifest format: </p> <p> <code>[ {"prefix": "s3://customer_bucket/some/prefix/"},</code> </p> <p> <code> "relative/path/to/custdata-1",</code> </p> <p> <code> "relative/path/custdata-2",</code> </p> <p> <code> ...</code> </p> <p> <code> "relative/path/custdata-N"</code> </p> <p> <code>]</code> </p> <p> This JSON is equivalent to the following <code>S3Uri</code> list:</p> <p> <code>s3://customer_bucket/some/prefix/relative/path/to/custdata-1</code> </p> <p> <code>s3://customer_bucket/some/prefix/relative/path/custdata-2</code> </p> <p> <code>...</code> </p> <p> <code>s3://customer_bucket/some/prefix/relative/path/custdata-N</code> </p> <p>The complete set of <code>S3Uri</code> in this manifest is the input data for the channel for this data source. The object that each <code>S3Uri</code> points to must be readable by the IAM role that SageMaker uses to perform tasks on your behalf. </p> </li> </ul>',
        }),
    ),
    S3DataDistributionType: S3DataDistributionSchema.and(
      z
        .any()
        .openapi({
          description:
            "<p>If you want SageMaker to replicate the entire dataset on each ML compute instance that is launched for model training, specify <code>FullyReplicated</code>. </p> <p>If you want SageMaker to replicate a subset of data on each ML compute instance that is launched for model training, specify <code>ShardedByS3Key</code>. If there are <i>n</i> ML compute instances launched for a training job, each instance gets approximately 1/<i>n</i> of the number of S3 objects. In this case, model training on each machine uses only the subset of training data. </p> <p>Don't choose more ML compute instances for training than available S3 objects. If you do, some nodes won't get any data and you will pay for nodes that aren't getting any training data. This applies in both File and Pipe modes. Keep this in mind when developing algorithms. </p> <p>In distributed training, where you use multiple ML compute EC2 instances, you might choose <code>ShardedByS3Key</code>. If the algorithm requires copying training data to the ML storage volume (when <code>TrainingInputMode</code> is set to <code>File</code>), this copies 1/<i>n</i> of the number of objects. </p>",
        }),
    ).exactOptional(),
    AttributeNames: AttributeNamesSchema.and(
      z
        .any()
        .openapi({
          description:
            'A list of one or more attribute names to use that are found in a specified augmented manifest file.',
        }),
    ).exactOptional(),
    InstanceGroupNames: InstanceGroupNamesSchema.and(
      z
        .any()
        .openapi({
          description: 'A list of names of instance groups that get data from the S3 data source.',
        }),
    ).exactOptional(),
  })
  .openapi({ required: ['S3DataType', 'S3Uri'], description: 'Describes the S3 data source.' })
  .openapi('S3DataSource')

const FileSystemIdSchema = z.string().regex(/.*/).min(11).openapi('FileSystemId')

const FileSystemAccessModeSchema = z.enum(['rw', 'ro']).openapi('FileSystemAccessMode')

const FileSystemTypeSchema = z.enum(['EFS', 'FSxLustre']).openapi('FileSystemType')

const DirectoryPathSchema = z.string().regex(/.*/).max(4096).openapi('DirectoryPath')

const FileSystemDataSourceSchema = z
  .object({
    FileSystemId: FileSystemIdSchema.and(z.any().openapi({ description: 'The file system id.' })),
    FileSystemAccessMode: FileSystemAccessModeSchema.and(
      z
        .any()
        .openapi({
          description:
            'The access mode of the mount of the directory associated with the channel. A directory can be mounted either in <code>ro</code> (read-only) or <code>rw</code> (read-write) mode.',
        }),
    ),
    FileSystemType: FileSystemTypeSchema.and(
      z.any().openapi({ description: 'The file system type. ' }),
    ),
    DirectoryPath: DirectoryPathSchema.and(
      z
        .any()
        .openapi({ description: 'The full path to the directory to associate with the channel.' }),
    ),
  })
  .openapi({
    required: ['FileSystemId', 'FileSystemAccessMode', 'FileSystemType', 'DirectoryPath'],
    description: 'Specifies a file system data source for a channel.',
  })
  .openapi('FileSystemDataSource')

type DataSourceType = {
  S3DataSource?: z.infer<typeof S3DataSourceSchema> & { [key: string]: unknown }
  FileSystemDataSource?: z.infer<typeof FileSystemDataSourceSchema> & { [key: string]: unknown }
}

const DataInputConfigSchema = z
  .string()
  .regex(/[\S\s]+/)
  .min(1)
  .max(1024)
  .openapi('DataInputConfig')

const FrameworkSchema = z
  .enum([
    'TENSORFLOW',
    'KERAS',
    'MXNET',
    'ONNX',
    'PYTORCH',
    'XGBOOST',
    'TFLITE',
    'DARKNET',
    'SKLEARN',
  ])
  .openapi('Framework')

const FrameworkVersionSchema = z
  .string()
  .regex(/[0-9]\.[A-Za-z0-9.]+/)
  .min(3)
  .max(10)
  .openapi('FrameworkVersion')

type InputConfigType = {
  S3Uri: z.infer<typeof S3UriSchema> & { [key: string]: unknown }
  DataInputConfig: z.infer<typeof DataInputConfigSchema> & { [key: string]: unknown }
  Framework: z.infer<typeof FrameworkSchema> & { [key: string]: unknown }
  FrameworkVersion?: z.infer<typeof FrameworkVersionSchema> & { [key: string]: unknown }
}

const SecurityGroupIdSchema = z
  .string()
  .regex(/[-0-9a-zA-Z]+/)
  .max(32)
  .openapi('SecurityGroupId')

const DomainSecurityGroupIdsSchema = z
  .array(SecurityGroupIdSchema)
  .max(3)
  .openapi('DomainSecurityGroupIds')

const RoleArnSchema = z
  .string()
  .regex(/^arn:aws[a-z\-]*:iam::\d{12}:role\/?[a-zA-Z_0-9+=,.@\-_\/]+$/)
  .min(20)
  .max(2048)
  .openapi('RoleArn')

const StringSchema = z.string().openapi('String')

const ImageArnSchema = z
  .string()
  .regex(/^arn:aws(-[\w]+)*:sagemaker:.+:[0-9]{12}:image\/[a-z0-9]([-.]?[a-z0-9])*$/)
  .max(256)
  .openapi('ImageArn')

const ImageVersionArnSchema = z
  .string()
  .regex(
    /^arn:aws(-[\w]+)*:sagemaker:.+:[0-9]{12}:image-version\/[a-z0-9]([-.]?[a-z0-9])*\/[0-9]+$/,
  )
  .max(256)
  .openapi('ImageVersionArn')

