const CreateAutoMLJobRequestSchema = z
  .object({
    AutoMLJobName: AutoMLJobNameSchema.and(
      z
        .any()
        .openapi({
          description:
            'Identifies an Autopilot job. The name must be unique to your account and is case insensitive.',
        }),
    ),
    InputDataConfig: AutoMLInputDataConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'An array of channel objects that describes the input data and its location. Each channel is a named input source. Similar to <code>InputDataConfig</code> supported by <a href="https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_HyperParameterTrainingJobDefinition.html">HyperParameterTrainingJobDefinition</a>. Format(s) supported: CSV, Parquet. A minimum of 500 rows is required for the training dataset. There is not a minimum number of rows required for the validation dataset.',
        }),
    ),
    OutputDataConfig: AutoMLOutputDataConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'Provides information about encryption and the Amazon S3 output path needed to store artifacts from an AutoML job. Format(s) supported: CSV.',
        }),
    ),
    ProblemType: ProblemTypeSchema.and(
      z
        .any()
        .openapi({
          description:
            'Defines the type of supervised learning problem available for the candidates. For more information, see <a href="https://docs.aws.amazon.com/sagemaker/latest/dg/autopilot-datasets-problem-types.html#autopilot-problem-types"> Amazon SageMaker Autopilot problem types</a>.',
        }),
    ).exactOptional(),
    AutoMLJobObjective: AutoMLJobObjectiveSchema.and(
      z
        .any()
        .openapi({
          description:
            'Defines the objective metric used to measure the predictive quality of an AutoML job. You provide an <a href="https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_AutoMLJobObjective.html">AutoMLJobObjective$MetricName</a> and Autopilot infers whether to minimize or maximize it. For <a href="https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_CreateAutoMLJobV2.html">CreateAutoMLJobV2</a>, only <code>Accuracy</code> is supported.',
        }),
    ).exactOptional(),
    AutoMLJobConfig: AutoMLJobConfigSchema.and(
      z.any().openapi({ description: 'A collection of settings used to configure an AutoML job.' }),
    ).exactOptional(),
    RoleArn: RoleArnSchema.and(
      z.any().openapi({ description: 'The ARN of the role that is used to access the data.' }),
    ),
    GenerateCandidateDefinitionsOnly: GenerateCandidateDefinitionsOnlySchema.and(
      z
        .any()
        .openapi({
          description:
            'Generates possible candidates without training the models. A candidate is a combination of data preprocessors, algorithms, and algorithm parameter settings.',
        }),
    ).exactOptional(),
    Tags: TagListSchema.and(
      z
        .any()
        .openapi({
          description:
            'An array of key-value pairs. You can use tags to categorize your Amazon Web Services resources in different ways, for example, by purpose, owner, or environment. For more information, see <a href="https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html">Tagging Amazon Web ServicesResources</a>. Tag keys must be unique per resource.',
        }),
    ).exactOptional(),
    ModelDeployConfig: ModelDeployConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'Specifies how to generate the endpoint name for an automatic one-click Autopilot model deployment.',
        }),
    ).exactOptional(),
  })
  .openapi({
    required: ['AutoMLJobName', 'InputDataConfig', 'OutputDataConfig', 'RoleArn'],
    title: 'CreateAutoMLJobRequest',
  })
  .openapi('CreateAutoMLJobRequest')

const CreateAutoMLJobV2ResponseSchema = z
