const AutoMLJobChannelSchema = z
  .object({
    ChannelType: AutoMLChannelTypeSchema.and(
      z
        .any()
        .openapi({
          description:
            'The type of channel. Defines whether the data are used for training or validation. The default value is <code>training</code>. Channels for <code>training</code> and <code>validation</code> must share the same <code>ContentType</code> ',
        }),
    ).exactOptional(),
    ContentType: ContentTypeSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The content type of the data from the input source. The following are the allowed content types for different problems:</p> <ul> <li> <p>ImageClassification: <code>image/png</code>, <code>image/jpeg</code>, <code>image/*</code> </p> </li> <li> <p>TextClassification: <code>text/csv;header=present</code> </p> </li> </ul>',
        }),
    ).exactOptional(),
    CompressionType: CompressionTypeSchema.and(
      z
        .any()
        .openapi({
          description:
            'The allowed compression types depend on the input format. We allow the compression type <code>Gzip</code> for <code>S3Prefix</code> inputs only. For all other inputs, the compression type should be <code>None</code>. If no compression type is provided, we default to <code>None</code>.',
        }),
    ).exactOptional(),
    DataSource: AutoMLDataSourceSchema.and(
      z.any().openapi({ description: 'The data source for an AutoML channel.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'A channel is a named input source that training algorithms can consume. This channel is used for the non tabular training data of an AutoML job using the V2 API. For tabular training data, see <a href="https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_AutoMLChannel.html"> AutoMLChannel</a>. For more information, see <a href="https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_Channel.html"> Channel</a>.',
    required: [],
  })
  .openapi('AutoMLJobChannel')

