const RecommendationJobNameSchema = z
  .string()
  .regex(/^[a-zA-Z0-9](-*[a-zA-Z0-9]){0,63}/)
  .min(1)
  .max(64)
  .openapi('RecommendationJobName')

const RecommendationJobTypeSchema = z.enum(['Default', 'Advanced']).openapi('RecommendationJobType')

const JobDurationInSecondsSchema = z.int().min(1).openapi('JobDurationInSeconds')

const TrafficTypeSchema = z.literal('PHASES').openapi('TrafficType')

const InitialNumberOfUsersSchema = z.int().min(1).openapi('InitialNumberOfUsers')

const SpawnRateSchema = z.int().min(0).openapi('SpawnRate')

const TrafficDurationInSecondsSchema = z.int().min(1).openapi('TrafficDurationInSeconds')

const PhaseSchema = z
  .object({
    InitialNumberOfUsers: InitialNumberOfUsersSchema.and(
      z.any().openapi({ description: 'Specifies how many concurrent users to start with.' }),
    ).exactOptional(),
    SpawnRate: SpawnRateSchema.and(
      z.any().openapi({ description: 'Specified how many new users to spawn in a minute.' }),
    ).exactOptional(),
    DurationInSeconds: TrafficDurationInSecondsSchema.and(
      z.any().openapi({ description: 'Specifies how long traffic phase should be.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'Defines the traffic pattern.', required: [] })
  .openapi('Phase')

const PhasesSchema = z.array(PhaseSchema).min(1).openapi('Phases')

const TrafficPatternSchema = z
  .object({
    TrafficType: TrafficTypeSchema.and(
      z.any().openapi({ description: 'Defines the traffic patterns.' }),
    ).exactOptional(),
    Phases: PhasesSchema.and(
      z.any().openapi({ description: 'Defines the phases traffic specification.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'Defines the traffic pattern of the load test.', required: [] })
  .openapi('TrafficPattern')

const MaxNumberOfTestsSchema = z.int().min(1).openapi('MaxNumberOfTests')

const MaxParallelOfTestsSchema = z.int().min(1).openapi('MaxParallelOfTests')

const RecommendationJobResourceLimitSchema = z
  .object({
    MaxNumberOfTests: MaxNumberOfTestsSchema.and(
      z.any().openapi({ description: 'Defines the maximum number of load tests.' }),
    ).exactOptional(),
    MaxParallelOfTests: MaxParallelOfTestsSchema.and(
      z.any().openapi({ description: 'Defines the maximum number of parallel load tests.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Specifies the maximum number of jobs that can run in parallel and the maximum number of jobs that can run.',
    required: [],
  })
  .openapi('RecommendationJobResourceLimit')

const InferenceSpecificationNameSchema = z
  .string()
  .regex(/^[a-zA-Z0-9](-*[a-zA-Z0-9]){0,62}$/)
  .min(1)
  .max(63)
  .openapi('InferenceSpecificationName')

const String64Schema = z.string().max(64).openapi('String64')

const String128Schema = z.string().max(128).openapi('String128')

const CategoricalParameterRangeValuesSchema = z
  .array(String128Schema)
  .min(1)
  .max(3)
  .openapi('CategoricalParameterRangeValues')

const CategoricalParameterSchema = z
  .object({
    Name: String64Schema.and(
      z.any().openapi({ description: 'The Name of the environment variable.' }),
    ),
    Value: CategoricalParameterRangeValuesSchema.and(
      z.any().openapi({ description: 'The list of values you can pass.' }),
    ),
  })
  .openapi({
    required: ['Name', 'Value'],
    description: 'Environment parameters you want to benchmark your load test against.',
  })
  .openapi('CategoricalParameter')

const CategoricalParametersSchema = z
  .array(CategoricalParameterSchema)
  .min(1)
  .max(5)
  .openapi('CategoricalParameters')

const EnvironmentParameterRangesSchema = z
  .object({
    CategoricalParameterRanges: CategoricalParametersSchema.and(
      z.any().openapi({ description: 'Specified a list of parameters for each category.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'Specifies the range of environment parameters', required: [] })
  .openapi('EnvironmentParameterRanges')

const EndpointInputConfigurationSchema = z
  .object({
    InstanceType: ProductionVariantInstanceTypeSchema.and(
      z.any().openapi({ description: 'The instance types to use for the load test.' }),
    ),
    InferenceSpecificationName: InferenceSpecificationNameSchema.and(
      z
        .any()
        .openapi({ description: 'The inference specification name in the model package version.' }),
    ).exactOptional(),
    EnvironmentParameterRanges: EnvironmentParameterRangesSchema.and(
      z.any().openapi({ description: ' The parameter you want to benchmark against.' }),
    ).exactOptional(),
  })
  .openapi({
    required: ['InstanceType'],
    description: 'The endpoint configuration for the load test.',
  })
  .openapi('EndpointInputConfiguration')

const EndpointInputConfigurationsSchema = z
  .array(EndpointInputConfigurationSchema)
  .min(1)
  .max(10)
  .openapi('EndpointInputConfigurations')

const RecommendationJobSupportedContentTypesSchema = z
  .array(StringSchema)
  .openapi('RecommendationJobSupportedContentTypes')

const RecommendationJobPayloadConfigSchema = z
  .object({
    SamplePayloadUrl: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            'The Amazon Simple Storage Service (Amazon S3) path where the sample payload is stored. This path must point to a single gzip compressed tar archive (.tar.gz suffix).',
        }),
    ).exactOptional(),
    SupportedContentTypes: RecommendationJobSupportedContentTypesSchema.and(
      z.any().openapi({ description: 'The supported MIME types for the input data.' }),
    ).exactOptional(),
  })
  .openapi({
    description: 'The configuration for the payload for a recommendation job.',
    required: [],
  })
  .openapi('RecommendationJobPayloadConfig')

const RecommendationJobSupportedInstanceTypesSchema = z
  .array(StringSchema)
  .openapi('RecommendationJobSupportedInstanceTypes')

const RecommendationJobDataInputConfigSchema = z
  .string()
  .regex(/[\S\s]+/)
  .min(1)
  .max(1024)
  .openapi('RecommendationJobDataInputConfig')

const RecommendationJobContainerConfigSchema = z
  .object({
    Domain: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The machine learning domain of the model and its components.</p> <p>Valid Values: <code>COMPUTER_VISION | NATURAL_LANGUAGE_PROCESSING | MACHINE_LEARNING</code> </p>',
        }),
    ).exactOptional(),
    Task: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The machine learning task that the model accomplishes.</p> <p>Valid Values: <code>IMAGE_CLASSIFICATION | OBJECT_DETECTION | TEXT_GENERATION | IMAGE_SEGMENTATION | FILL_MASK | CLASSIFICATION | REGRESSION | OTHER</code> </p>',
        }),
    ).exactOptional(),
    Framework: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The machine learning framework of the container image.</p> <p>Valid Values: <code>TENSORFLOW | PYTORCH | XGBOOST | SAGEMAKER-SCIKIT-LEARN</code> </p>',
        }),
    ).exactOptional(),
    FrameworkVersion: StringSchema.and(
      z.any().openapi({ description: 'The framework version of the container image.' }),
    ).exactOptional(),
    PayloadConfig: RecommendationJobPayloadConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'Specifies the <code>SamplePayloadUrl</code> and all other sample payload-related fields.',
        }),
    ).exactOptional(),
    NearestModelName: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The name of a pre-trained machine learning model benchmarked by Amazon SageMaker Inference Recommender that matches your model.</p> <p>Valid Values: <code>efficientnetb7 | unet | xgboost | faster-rcnn-resnet101 | nasnetlarge | vgg16 | inception-v3 | mask-rcnn | sagemaker-scikit-learn | densenet201-gluon | resnet18v2-gluon | xception | densenet201 | yolov4 | resnet152 | bert-base-cased | xceptionV1-keras | resnet50 | retinanet</code> </p>',
        }),
    ).exactOptional(),
    SupportedInstanceTypes: RecommendationJobSupportedInstanceTypesSchema.and(
      z
        .any()
        .openapi({
          description:
            'A list of the instance types that are used to generate inferences in real-time.',
        }),
    ).exactOptional(),
    DataInputConfig: RecommendationJobDataInputConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'Specifies the name and shape of the expected data inputs for your trained model with a JSON dictionary form. This field is used for optimizing your model using SageMaker Neo. For more information, see <a href="https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_InputConfig.html#sagemaker-Type-InputConfig-DataInputConfig">DataInputConfig</a>.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Specifies mandatory fields for running an Inference Recommender job directly in the <a href="https://docs.aws.amazon.com/sagemaker/latest/APIReference/API_CreateInferenceRecommendationsJob.html">CreateInferenceRecommendationsJob</a> API. The fields specified in <code>ContainerConfig</code> override the corresponding fields in the model package. Use <code>ContainerConfig</code> if you want to specify these fields for the recommendation job but don\'t want to edit them in your model package.',
    required: [],
  })
  .openapi('RecommendationJobContainerConfig')

const EndpointInfoSchema = z
  .object({
    EndpointName: EndpointNameSchema.and(
      z.any().openapi({ description: "The name of a customer's endpoint." }),
    ),
  })
  .openapi({
    required: ['EndpointName'],
    description:
      'Details about a customer endpoint that was compared in an Inference Recommender job.',
  })
  .openapi('EndpointInfo')

const EndpointsSchema = z.array(EndpointInfoSchema).max(1).openapi('Endpoints')

const RecommendationJobVpcSecurityGroupIdSchema = z
  .string()
  .regex(/[-0-9a-zA-Z]+/)
  .max(32)
  .openapi('RecommendationJobVpcSecurityGroupId')

const RecommendationJobVpcSecurityGroupIdsSchema = z
  .array(RecommendationJobVpcSecurityGroupIdSchema)
  .min(1)
  .max(5)
  .openapi('RecommendationJobVpcSecurityGroupIds')

const RecommendationJobVpcSubnetIdSchema = z
  .string()
  .regex(/[-0-9a-zA-Z]+/)
  .max(32)
  .openapi('RecommendationJobVpcSubnetId')

const RecommendationJobVpcSubnetsSchema = z
  .array(RecommendationJobVpcSubnetIdSchema)
  .min(1)
  .max(16)
  .openapi('RecommendationJobVpcSubnets')

const RecommendationJobVpcConfigSchema = z
  .object({
    SecurityGroupIds: RecommendationJobVpcSecurityGroupIdsSchema.and(
      z
        .any()
        .openapi({
          description:
            'The VPC security group IDs. IDs have the form of <code>sg-xxxxxxxx</code>. Specify the security groups for the VPC that is specified in the <code>Subnets</code> field.',
        }),
    ),
    Subnets: RecommendationJobVpcSubnetsSchema.and(
      z
        .any()
        .openapi({
          description: 'The ID of the subnets in the VPC to which you want to connect your model.',
        }),
    ),
  })
  .openapi({
    required: ['SecurityGroupIds', 'Subnets'],
    description:
      'Inference Recommender provisions SageMaker endpoints with access to VPC in the inference recommendation job.',
  })
  .openapi('RecommendationJobVpcConfig')

const RecommendationJobInputConfigSchema = z
  .object({
    ModelPackageVersionArn: ModelPackageArnSchema.and(
      z
        .any()
        .openapi({ description: 'The Amazon Resource Name (ARN) of a versioned model package.' }),
    ).exactOptional(),
    JobDurationInSeconds: JobDurationInSecondsSchema.and(
      z
        .any()
        .openapi({ description: 'Specifies the maximum duration of the job, in seconds.&gt;' }),
    ).exactOptional(),
    TrafficPattern: TrafficPatternSchema.and(
      z.any().openapi({ description: 'Specifies the traffic pattern of the job.' }),
    ).exactOptional(),
    ResourceLimit: RecommendationJobResourceLimitSchema.and(
      z.any().openapi({ description: 'Defines the resource limit of the job.' }),
    ).exactOptional(),
    EndpointConfigurations: EndpointInputConfigurationsSchema.and(
      z.any().openapi({ description: 'Specifies the endpoint configuration to use for a job.' }),
    ).exactOptional(),
    VolumeKmsKeyId: KmsKeyIdSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The Amazon Resource Name (ARN) of a Amazon Web Services Key Management Service (Amazon Web Services KMS) key that Amazon SageMaker uses to encrypt data on the storage volume attached to the ML compute instance that hosts the endpoint. This key will be passed to SageMaker Hosting for endpoint creation. </p> <p>The SageMaker execution role must have <code>kms:CreateGrant</code> permission in order to encrypt data on the storage volume of the endpoints created for inference recommendation. The inference recommendation job will fail asynchronously during endpoint configuration creation if the role passed does not have <code>kms:CreateGrant</code> permission.</p> <p>The <code>KmsKeyId</code> can be any of the following formats:</p> <ul> <li> <p>// KMS Key ID</p> <p> <code>"1234abcd-12ab-34cd-56ef-1234567890ab"</code> </p> </li> <li> <p>// Amazon Resource Name (ARN) of a KMS Key</p> <p> <code>"arn:aws:kms:&lt;region&gt;:&lt;account&gt;:key/&lt;key-id-12ab-34cd-56ef-1234567890ab&gt;"</code> </p> </li> <li> <p>// KMS Key Alias</p> <p> <code>"alias/ExampleAlias"</code> </p> </li> <li> <p>// Amazon Resource Name (ARN) of a KMS Key Alias</p> <p> <code>"arn:aws:kms:&lt;region&gt;:&lt;account&gt;:alias/&lt;ExampleAlias&gt;"</code> </p> </li> </ul> <p>For more information about key identifiers, see <a href="https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#key-id-key-id">Key identifiers (KeyID)</a> in the Amazon Web Services Key Management Service (Amazon Web Services KMS) documentation.</p>',
        }),
    ).exactOptional(),
    ContainerConfig: RecommendationJobContainerConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'Specifies mandatory fields for running an Inference Recommender job. The fields specified in <code>ContainerConfig</code> override the corresponding fields in the model package.',
        }),
    ).exactOptional(),
    Endpoints: EndpointsSchema.and(
      z
        .any()
        .openapi({
          description: 'Existing customer endpoints on which to run an Inference Recommender job.',
        }),
    ).exactOptional(),
    VpcConfig: RecommendationJobVpcConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'Inference Recommender provisions SageMaker endpoints with access to VPC in the inference recommendation job.',
        }),
    ).exactOptional(),
    ModelName: ModelNameSchema.and(
      z.any().openapi({ description: 'The name of the created model.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'The input configuration of the recommendation job.', required: [] })
  .openapi('RecommendationJobInputConfig')

const RecommendationJobDescriptionSchema = z
  .string()
  .max(128)
  .openapi('RecommendationJobDescription')

const IntegerSchema = z.int().openapi('Integer')

const ModelLatencyThresholdSchema = z
  .object({
    Percentile: String64Schema.and(
      z.any().openapi({ description: 'The model latency percentile threshold.' }),
    ).exactOptional(),
    ValueInMilliseconds: IntegerSchema.and(
      z.any().openapi({ description: 'The model latency percentile value in milliseconds.' }),
    ).exactOptional(),
  })
  .openapi({ description: 'The model latency threshold.', required: [] })
  .openapi('ModelLatencyThreshold')

const ModelLatencyThresholdsSchema = z
  .array(ModelLatencyThresholdSchema)
  .length(1)
  .openapi('ModelLatencyThresholds')

const RecommendationJobStoppingConditionsSchema = z
  .object({
    MaxInvocations: IntegerSchema.and(
      z
        .any()
        .openapi({
          description: 'The maximum number of requests per minute expected for the endpoint.',
        }),
    ).exactOptional(),
    ModelLatencyThresholds: ModelLatencyThresholdsSchema.and(
      z
        .any()
        .openapi({
          description:
            'The interval of time taken by a model to respond as viewed from SageMaker. The interval includes the local communication time taken to send the request and to fetch the response from the container of a model and the time taken to complete the inference in the container.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description:
      'Specifies conditions for stopping a job. When a job reaches a stopping condition limit, SageMaker ends the job.',
    required: [],
  })
  .openapi('RecommendationJobStoppingConditions')

const RecommendationJobCompiledOutputConfigSchema = z
  .object({
    S3OutputUri: S3UriSchema.and(
      z
        .any()
        .openapi({
          description:
            'Identifies the Amazon S3 bucket where you want SageMaker to store the compiled model artifacts.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description: 'Provides information about the output configuration for the compiled model.',
    required: [],
  })
  .openapi('RecommendationJobCompiledOutputConfig')

const RecommendationJobOutputConfigSchema = z
  .object({
    KmsKeyId: KmsKeyIdSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The Amazon Resource Name (ARN) of a Amazon Web Services Key Management Service (Amazon Web Services KMS) key that Amazon SageMaker uses to encrypt your output artifacts with Amazon S3 server-side encryption. The SageMaker execution role must have <code>kms:GenerateDataKey</code> permission.</p> <p>The <code>KmsKeyId</code> can be any of the following formats:</p> <ul> <li> <p>// KMS Key ID</p> <p> <code>"1234abcd-12ab-34cd-56ef-1234567890ab"</code> </p> </li> <li> <p>// Amazon Resource Name (ARN) of a KMS Key</p> <p> <code>"arn:aws:kms:&lt;region&gt;:&lt;account&gt;:key/&lt;key-id-12ab-34cd-56ef-1234567890ab&gt;"</code> </p> </li> <li> <p>// KMS Key Alias</p> <p> <code>"alias/ExampleAlias"</code> </p> </li> <li> <p>// Amazon Resource Name (ARN) of a KMS Key Alias</p> <p> <code>"arn:aws:kms:&lt;region&gt;:&lt;account&gt;:alias/&lt;ExampleAlias&gt;"</code> </p> </li> </ul> <p>For more information about key identifiers, see <a href="https://docs.aws.amazon.com/kms/latest/developerguide/concepts.html#key-id-key-id">Key identifiers (KeyID)</a> in the Amazon Web Services Key Management Service (Amazon Web Services KMS) documentation.</p>',
        }),
    ).exactOptional(),
    CompiledOutputConfig: RecommendationJobCompiledOutputConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'Provides information about the output configuration for the compiled model.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description: 'Provides information about the output configuration for the compiled model.',
    required: [],
  })
  .openapi('RecommendationJobOutputConfig')

const CreateInferenceRecommendationsJobRequestSchema = z
  .object({
    JobName: RecommendationJobNameSchema.and(
      z
        .any()
        .openapi({
          description:
            'A name for the recommendation job. The name must be unique within the Amazon Web Services Region and within your Amazon Web Services account. The job name is passed down to the resources created by the recommendation job. The names of resources (such as the model, endpoint configuration, endpoint, and compilation) that are prefixed with the job name are truncated at 40 characters.',
        }),
    ),
    JobType: RecommendationJobTypeSchema.and(
      z
        .any()
        .openapi({
          description:
            'Defines the type of recommendation job. Specify <code>Default</code> to initiate an instance recommendation and <code>Advanced</code> to initiate a load test. If left unspecified, Amazon SageMaker Inference Recommender will run an instance recommendation (<code>DEFAULT</code>) job.',
        }),
    ),
    RoleArn: RoleArnSchema.and(
      z
        .any()
        .openapi({
          description:
            'The Amazon Resource Name (ARN) of an IAM role that enables Amazon SageMaker to perform tasks on your behalf.',
        }),
    ),
    InputConfig: RecommendationJobInputConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'Provides information about the versioned model package Amazon Resource Name (ARN), the traffic pattern, and endpoint configurations.',
        }),
    ),
    JobDescription: RecommendationJobDescriptionSchema.and(
      z.any().openapi({ description: 'Description of the recommendation job.' }),
    ).exactOptional(),
    StoppingConditions: RecommendationJobStoppingConditionsSchema.and(
      z
        .any()
        .openapi({
          description:
            'A set of conditions for stopping a recommendation job. If any of the conditions are met, the job is automatically stopped.',
        }),
    ).exactOptional(),
    OutputConfig: RecommendationJobOutputConfigSchema.and(
      z
        .any()
        .openapi({
          description:
            'Provides information about the output artifacts and the KMS key to use for Amazon S3 server-side encryption.',
        }),
    ).exactOptional(),
    Tags: TagListSchema.and(
      z
        .any()
        .openapi({
          description:
            'The metadata that you apply to Amazon Web Services resources to help you categorize and organize them. Each tag consists of a key and a value, both of which you define. For more information, see <a href="https://docs.aws.amazon.com/general/latest/gr/aws_tagging.html">Tagging Amazon Web Services Resources</a> in the Amazon Web Services General Reference.',
        }),
    ).exactOptional(),
  })
  .openapi({
    required: ['JobName', 'JobType', 'RoleArn', 'InputConfig'],
    title: 'CreateInferenceRecommendationsJobRequest',
  })
  .openapi('CreateInferenceRecommendationsJobRequest')

const LabelingJobArnSchema = z
  .string()
  .regex(/arn:aws[a-z\-]*:sagemaker:[a-z0-9\-]*:[0-9]{12}:labeling-job\/.*/)
